import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { AlertComponent } from './_components';
import { AccountService } from './_services';
import { Account } from './_models';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.less'],
  standalone: true,
  imports: [CommonModule, RouterModule, AlertComponent]
})
export class AppComponent {
  title = 'Angular 21 Boilerplate';
  accountValue?: Account | null;

  constructor(private accountService: AccountService) {
    this.accountService.account$.subscribe(x => this.accountValue = x);
  }

  logout() {
    this.accountService.logout();
  }
}
<nav class="navbar navbar-expand navbar-dark bg-dark px-3">
  <div class="navbar-nav">
    <a class="nav-item nav-link" routerLink="/">Home</a>
    <button *ngIf="accountValue" class="btn btn-link nav-item nav-link" (click)="logout()">Logout</button>
    <a *ngIf="!accountValue" class="nav-item nav-link" routerLink="/account/login">Login</a>
  </div>
</nav>

<div class="p-3">
  <div class="container-fluid">
    <app-alert></app-alert>
    <router-outlet></router-outlet>
  </div>
</div>
